/// <reference types="svelte" />
/**
 * Store: mart auto-purchase modal.
 */

import { facade } from '@bus/facade';
import { GameEventType as Evt } from '../bus/events.js';
import type { GameRuntime } from '../types/game.js';
import {
  buildMartAutoPurchaseSnapshot,
  isMartAutoPurchaseModalVisible,
  type MartAutoPurchaseSnapshot,
} from '../lib/martAutoPurchaseSnapshot.ts';

class MartAutoPurchaseStore {
  snapshot: MartAutoPurchaseSnapshot | null = $state(null);
}

export const martAutoPurchase = new MartAutoPurchaseStore();

function getGame(): GameRuntime | null {
  return (globalThis as { game?: GameRuntime }).game ?? null;
}

function refreshFromGame(): void {
  const g = getGame();
  martAutoPurchase.snapshot = g ? buildMartAutoPurchaseSnapshot(g) : null;
}

facade.subscribe(Evt.MART_AUTO_PURCHASE_UPDATED, () => {
  refreshFromGame();
});

facade.subscribe(Evt.MODAL_OPENED, (evt) => {
  if (evt.type === Evt.MODAL_OPENED && evt.modalId === 'martAutoPurchaseModal') {
    refreshFromGame();
  }
});

facade.subscribe(Evt.MODAL_CLOSED, (evt) => {
  if (evt.type === Evt.MODAL_CLOSED && evt.modalId === 'martAutoPurchaseModal') {
    martAutoPurchase.snapshot = null;
  }
});

facade.subscribe(Evt.LANGUAGE_CHANGED, () => {
  if (isMartAutoPurchaseModalVisible()) {
    refreshFromGame();
  }
});
